// The seam between spaday and transports — and the one place either layer meets the other.
//
// spaday owns the UI: a component tree, reactive `bindings`, and the signal `Store` they read/write
// (see signals.ts). It knows nothing about the wire. transports owns the wire: it mirrors an
// authoritative model and exposes a `Client` to read/edit it. It knows nothing about UI.
//
// `connectStore` marries them WITHOUT importing transports: it speaks to the client through the small
// `ModelClient` interface below — spaday's entire view of "the wire" — and
// converts between the wire's tagged values and plain JS via an injected `ValueCodec` (transports'
// `fromValue`/`toValue`). So the boundary is enforced in the types: bind a `Store` to a transports
// model and inbound patches flow model → fields → bound props, while a two-way control's change becomes
// a server-authoritative `edit`. Swap in any object satisfying `ModelClient` and spaday is none the wiser.

import {
  type CollectionDelta,
  type CollectionKey,
  type CollectionPathSegment,
  Store,
  type StoreChange,
} from "./signals";

/** Spaday's whole view of a transports `Client`: receive a frame, find the model, read it, edit it. */
type PathSeg = { Key: string } | { Index: number };
type PatchOp =
  | { Set: { path: PathSeg[]; value: unknown } }
  | { Remove: { path: PathSeg[] } }
  | { Insert: { path: PathSeg[]; index: number; value: unknown } }
  | { RemoveAt: { path: PathSeg[]; index: number } }
  | { Move: { path: PathSeg[]; from: number; to: number } }
  | { Reorder: { path: PathSeg[]; order: number[] } };
type CrdtPathSeg =
  | { kind: "key"; key: string }
  | { kind: "member"; key: string }
  | {
      kind: "element";
      id: { dot: { counter: number; replica: string }; index: number };
    };
type CrdtMutation =
  | { kind: "map_set"; path: CrdtPathSeg[]; key: string; value: unknown }
  | { kind: "map_remove"; path: CrdtPathSeg[]; key: string }
  | { kind: "set_add"; path: CrdtPathSeg[]; value: unknown }
  | { kind: "set_remove"; path: CrdtPathSeg[]; key: string }
  | {
      kind: "sequence_insert";
      path: CrdtPathSeg[];
      after: Extract<CrdtPathSeg, { kind: "element" }>["id"] | null;
      values: unknown[];
    }
  | {
      kind: "sequence_delete";
      path: CrdtPathSeg[];
      ids: Extract<CrdtPathSeg, { kind: "element" }>["id"][];
    }
  | { kind: "register_set"; path: CrdtPathSeg[]; value: unknown }
  | {
      kind: "sequence_splice";
      path: CrdtPathSeg[];
      index: number;
      delete_count: number;
      values: unknown[];
    };
type CrdtPolicy =
  | { kind: "register" }
  | {
      kind: "map";
      fields?: Record<string, CrdtPolicy>;
      values?: CrdtPolicy;
    }
  | { kind: "set"; keys?: string[][]; element?: CrdtPolicy }
  | {
      kind: "sequence";
      materialization?: "list" | "string";
      element?: CrdtPolicy;
    };
type CrdtSpecView = { root: CrdtPolicy } | { toObject(): { root: CrdtPolicy } };
type CrdtOp = {
  kind: string;
  path: CrdtPathSeg[];
  key?: string;
};
type ReceiveChange =
  | { t: "snapshot"; id: number }
  | { t: "crdt_snapshot"; id: number }
  | {
      t: "patch";
      id: number;
      patch: { rev: number; ops: PatchOp[] };
      proposal?: string;
    }
  | { t: "crdt"; id: number; rev: number; ops: CrdtOp[] };
type AckChange =
  | (Extract<ReceiveChange, { t: "patch" | "crdt" }> & { proposal?: string })
  | { t: "ack"; id: number; rev: number; proposal: string };
type RejectChange = {
  t: "reject";
  id: number;
  rev: number;
  error: string;
  proposal?: string;
  crdt_ops?: CrdtOp[];
};

export interface ModelClient {
  recv(
    data: string | Uint8Array,
  ): ReceiveChange | ReceiveChange[] | undefined | void;
  /** Accepted-change listener provided by current transports clients. Optional for older clients. */
  onChange?(listener: (change: ReceiveChange) => void): () => void;
  onAck?(listener: (ack: AckChange) => void): () => void;
  onReject?(listener: (reject: RejectChange) => void): () => void;
  onAbandon?(listener: (proposals: string[]) => void): () => void;
  ids(): number[];
  typeName?(id: number): string | undefined;
  value(id: number): unknown; // the model as a tagged core Value
  edit(id: number, value: unknown, proposal?: string): string | Uint8Array; // an encoded edit frame to send back
  owns?(id: number, field: string): boolean;
  editOps?(id: number, ops: PatchOp[], proposal?: string): string | Uint8Array;
  proposeOps?(id: number, ops: PatchOp[], proposal?: string): boolean;
  editCrdt?(id: number, mutations: CrdtMutation[]): string | Uint8Array;
  proposeCrdt?(id: number, mutations: CrdtMutation[]): boolean;
  crdtSpec?(id: number): CrdtSpecView | undefined;
  crdtDiff?(id: number, value: unknown, path?: string[]): CrdtMutation[];
  abandonProposal?(proposal: string): boolean;
}

/** Convert between tagged core Values and plain JS fields (transports' `fromValue` / `toValue`). */
export interface ValueCodec {
  fromValue(value: unknown): unknown;
  toValue(plain: unknown): unknown;
}

export interface StoreLink {
  /** The selected model ID, once its snapshot arrives. */
  readonly modelId: number | undefined;
  /** Model selection failure; an ambiguous type disables this link. */
  readonly error: string | undefined;
  /** Subscribe to model-ID discovery. Late subscribers are called immediately. */
  onModel(listener: (id: number) => void): () => void;
  /** Feed an inbound wire frame; the mirrored model's fields flow into the store (and bound props). */
  receive(data: string | Uint8Array): void;
  /** Drop optimistic edits and reject new edits until another frame arrives. */
  disconnect(): void;
  /** Stop pushing store changes to the wire. */
  dispose(): void;
}

let nextStoreProposal = 1;

const isObj = (v: unknown): v is Record<string, unknown> =>
  v != null &&
  typeof v === "object" &&
  !Array.isArray(v) &&
  !ArrayBuffer.isView(v) &&
  !(v instanceof ArrayBuffer);

/** Flatten a model to [dotted-path, leaf] pairs — recursing plain objects (sub-models), not arrays. */
function* leaves(
  obj: Record<string, unknown>,
  prefix = "",
): Generator<[string, unknown]> {
  for (const [k, v] of Object.entries(obj)) {
    const path = prefix ? `${prefix}.${k}` : k;
    if (isObj(v)) yield* leaves(v, path);
    else yield [path, v];
  }
}

/** Immutably set a dotted path within a plain model, cloning each level. */
function setPath(
  obj: Record<string, unknown>,
  parts: string[],
  value: unknown,
): Record<string, unknown> {
  const [head, ...rest] = parts;
  const clone = { ...obj };
  clone[head] = rest.length
    ? setPath(isObj(clone[head]) ? clone[head] : {}, rest, value)
    : value;
  return clone;
}

function updatePath(
  value: unknown,
  path: PathSeg[],
  update: (current: unknown) => unknown,
): unknown {
  if (!path.length) return update(value);
  const [segment, ...rest] = path;
  if ("Key" in segment) {
    if (!isObj(value)) throw new Error("patch path expected an object");
    if (rest.length && !(segment.Key in value))
      throw new Error(
        `patch path key ${JSON.stringify(segment.Key)} not found`,
      );
    return {
      ...value,
      [segment.Key]: updatePath(value[segment.Key], rest, update),
    };
  }
  if (!Array.isArray(value)) throw new Error("patch path expected an array");
  if (
    !Number.isSafeInteger(segment.Index) ||
    segment.Index < 0 ||
    segment.Index >= value.length
  )
    throw new Error(
      `patch path index ${segment.Index} out of bounds (len ${value.length})`,
    );
  const next = [...value];
  next[segment.Index] = updatePath(next[segment.Index], rest, update);
  return next;
}

function applyPlainOp(
  current: unknown,
  path: PathSeg[],
  op: PatchOp,
  codec: ValueCodec,
): unknown {
  if ("Set" in op)
    return updatePath(current, path, () => codec.fromValue(op.Set.value));
  if ("Remove" in op) {
    if (!path.length) return undefined;
    const segment = path[path.length - 1];
    if (!segment || !("Key" in segment))
      throw new Error("remove path must end in an object key");
    return updatePath(current, path.slice(0, -1), (container) => {
      if (!isObj(container)) throw new Error("remove path expected an object");
      const next = { ...container };
      delete next[segment.Key];
      return next;
    });
  }
  if ("Insert" in op) {
    return updatePath(current, path, (container) => {
      if (!Array.isArray(container))
        throw new Error("insert path expected an array");
      if (
        !Number.isSafeInteger(op.Insert.index) ||
        op.Insert.index < 0 ||
        op.Insert.index > container.length
      )
        throw new Error(
          `insert index ${op.Insert.index} out of bounds (len ${container.length})`,
        );
      const next = [...container];
      next.splice(op.Insert.index, 0, codec.fromValue(op.Insert.value));
      return next;
    });
  }
  if ("Move" in op) {
    return updatePath(current, path, (container) => {
      if (!Array.isArray(container))
        throw new Error("move path expected an array");
      if (
        !Number.isSafeInteger(op.Move.from) ||
        op.Move.from < 0 ||
        op.Move.from >= container.length
      )
        throw new Error(
          `move source ${op.Move.from} out of bounds (len ${container.length})`,
        );
      if (
        !Number.isSafeInteger(op.Move.to) ||
        op.Move.to < 0 ||
        op.Move.to >= container.length
      )
        throw new Error(
          `move destination ${op.Move.to} out of bounds (len ${container.length})`,
        );
      const next = [...container];
      const [item] = next.splice(op.Move.from, 1);
      next.splice(op.Move.to, 0, item);
      return next;
    });
  }
  if ("Reorder" in op) {
    return updatePath(current, path, (container) => {
      if (!Array.isArray(container))
        throw new Error("reorder path expected an array");
      if (
        op.Reorder.order.length !== container.length ||
        op.Reorder.order.some(
          (index) =>
            !Number.isSafeInteger(index) ||
            index < 0 ||
            index >= container.length,
        ) ||
        new Set(op.Reorder.order).size !== container.length
      )
        throw new Error("reorder order must be a complete array permutation");
      return op.Reorder.order.map((index) => container[index]);
    });
  }
  return updatePath(current, path, (container) => {
    if (!Array.isArray(container))
      throw new Error("remove path expected an array");
    if (
      !Number.isSafeInteger(op.RemoveAt.index) ||
      op.RemoveAt.index < 0 ||
      op.RemoveAt.index >= container.length
    )
      throw new Error(
        `remove index ${op.RemoveAt.index} out of bounds (len ${container.length})`,
      );
    const next = [...container];
    next.splice(op.RemoveAt.index, 1);
    return next;
  });
}

function readSegments(value: unknown, path: readonly PathSeg[]): unknown {
  let current = value;
  for (const segment of path) {
    if ("Key" in segment) {
      if (!isObj(current)) return undefined;
      current = current[segment.Key];
    } else {
      if (!Array.isArray(current)) return undefined;
      current = current[segment.Index];
    }
  }
  return current;
}

function readCollectionKey(
  item: unknown,
  field: string,
): CollectionKey | undefined {
  let current = item;
  for (const part of field.split(".")) {
    if (Array.isArray(current)) {
      const index = Number(part);
      if (!Number.isSafeInteger(index) || index < 0 || index >= current.length)
        return undefined;
      current = current[index];
    } else if (isObj(current)) {
      current = current[part];
    } else {
      return undefined;
    }
  }
  return typeof current === "string" ||
    (typeof current === "number" && Number.isFinite(current))
    ? current
    : undefined;
}

function collectionDeltasMatch(
  current: readonly unknown[],
  next: readonly unknown[],
  deltas: readonly CollectionDelta[],
  itemKey: string,
): boolean {
  const identity = (item: unknown): string | undefined => {
    const key = readCollectionKey(item, itemKey);
    return key === undefined ? undefined : `${typeof key}:${key}`;
  };
  const order = current.map(identity);
  const target = next.map(identity);
  if (
    order.includes(undefined) ||
    target.includes(undefined) ||
    new Set(order).size !== order.length ||
    new Set(target).size !== target.length
  )
    return false;
  for (const delta of deltas) {
    if (delta.kind === "reset") return false;
    if (delta.kind === "reorder") {
      const reordered = delta.keys.map((key) => `${typeof key}:${key}`);
      const currentKeys = new Set(order);
      if (
        reordered.length !== order.length ||
        new Set(reordered).size !== reordered.length ||
        reordered.some((key) => !currentKeys.has(key))
      )
        return false;
      order.splice(0, order.length, ...reordered);
      continue;
    }
    const key = `${typeof delta.key}:${delta.key}`;
    const index = order.indexOf(key);
    if (delta.kind === "insert") {
      if (
        index !== -1 ||
        !Number.isSafeInteger(delta.index) ||
        delta.index < 0 ||
        delta.index > order.length ||
        identity(delta.item) !== key
      )
        return false;
      order.splice(delta.index, 0, key);
    } else if (delta.kind === "update") {
      if (index === -1) return false;
    } else if (delta.kind === "move") {
      if (
        index === -1 ||
        !Number.isSafeInteger(delta.index) ||
        delta.index < 0 ||
        delta.index >= order.length
      )
        return false;
      order.splice(index, 1);
      order.splice(delta.index, 0, key);
    } else {
      if (index === -1) return false;
      order.splice(index, 1);
    }
  }
  return (
    order.length === target.length &&
    order.every((key, index) => key === target[index])
  );
}

function collectionPath(path: readonly PathSeg[]): CollectionPathSegment[] {
  return path.map((segment) =>
    "Key" in segment ? segment.Key : segment.Index,
  );
}

function collectionDelta(
  current: unknown,
  next: unknown,
  path: PathSeg[],
  op: PatchOp,
  itemKey: string,
): CollectionDelta | undefined {
  if (!Array.isArray(current) || !Array.isArray(next)) return undefined;
  if ("Insert" in op && path.length === 0) {
    const item = next[op.Insert.index];
    const key = readCollectionKey(item, itemKey);
    return key === undefined
      ? undefined
      : { kind: "insert", key, index: op.Insert.index, item };
  }
  if ("RemoveAt" in op && path.length === 0) {
    const key = readCollectionKey(current[op.RemoveAt.index], itemKey);
    return key === undefined ? undefined : { kind: "remove", key };
  }
  if ("Move" in op && path.length === 0) {
    const key = readCollectionKey(current[op.Move.from], itemKey);
    return key === undefined ||
      !Object.is(key, readCollectionKey(next[op.Move.to], itemKey))
      ? undefined
      : { kind: "move", key, index: op.Move.to };
  }
  if ("Reorder" in op && path.length === 0) {
    const keys = next.map((item) => readCollectionKey(item, itemKey));
    return keys.includes(undefined)
      ? undefined
      : { kind: "reorder", keys: keys as CollectionKey[] };
  }
  const [row, ...itemPath] = path;
  if (!row || !("Index" in row)) return undefined;
  const oldItem = current[row.Index];
  const newItem = next[row.Index];
  const key = readCollectionKey(oldItem, itemKey);
  if (key === undefined || !Object.is(key, readCollectionKey(newItem, itemKey)))
    return undefined;

  let changedPath = itemPath;
  if ("Remove" in op) changedPath = itemPath.slice(0, -1);
  return {
    kind: "update",
    key,
    path: collectionPath(changedPath),
    value: readSegments(newItem, changedPath),
  };
}

const keyPath = (field: string): CrdtPathSeg[] =>
  field.split(".").map((key) => ({ kind: "key", key }));

function stringBoundary(value: string, offset: number): boolean {
  if (offset <= 0 || offset >= value.length) return true;
  const previous = value.charCodeAt(offset - 1);
  const next = value.charCodeAt(offset);
  return !(
    previous >= 0xd800 &&
    previous <= 0xdbff &&
    next >= 0xdc00 &&
    next <= 0xdfff
  );
}

function stringSplices(
  current: string,
  next: string,
  path: CrdtPathSeg[],
  change?: StoreChange,
): CrdtMutation[] {
  if (change?.ranges.length) {
    let cursor = 0;
    let rebuilt = "";
    let shift = 0;
    const mutations: CrdtMutation[] = [];
    for (const range of change.ranges) {
      if (
        !Number.isSafeInteger(range.from) ||
        !Number.isSafeInteger(range.to) ||
        range.from < cursor ||
        range.from > range.to ||
        range.to > current.length ||
        typeof range.insert !== "string" ||
        !stringBoundary(current, range.from) ||
        !stringBoundary(current, range.to)
      ) {
        mutations.length = 0;
        break;
      }
      const inserted = [...range.insert];
      // Editor offsets use UTF-16; CRDT sequence offsets count code points.
      const removed = Array.from(current.slice(range.from, range.to)).length;
      mutations.push({
        kind: "sequence_splice",
        path,
        index: Array.from(current.slice(0, range.from)).length + shift,
        delete_count: removed,
        values: inserted,
      });
      rebuilt += current.slice(cursor, range.from) + range.insert;
      cursor = range.to;
      shift += inserted.length - removed;
    }
    rebuilt += current.slice(cursor);
    if (mutations.length && rebuilt === next) return mutations;
  }

  const before = [...current];
  const after = [...next];
  let start = 0;
  const max = Math.min(before.length, after.length);
  while (start < max && before[start] === after[start]) start++;
  let end = 0;
  while (
    end < max - start &&
    before[before.length - 1 - end] === after[after.length - 1 - end]
  )
    end++;
  return [
    {
      kind: "sequence_splice",
      path,
      index: start,
      delete_count: before.length - start - end,
      values: after.slice(start, after.length - end),
    },
  ];
}

function arraySplice(
  current: readonly unknown[],
  next: readonly unknown[],
  path: CrdtPathSeg[],
): CrdtMutation {
  let start = 0;
  const max = Math.min(current.length, next.length);
  while (start < max && Object.is(current[start], next[start])) start++;
  let end = 0;
  while (
    end < max - start &&
    Object.is(current[current.length - 1 - end], next[next.length - 1 - end])
  )
    end++;
  return {
    kind: "sequence_splice",
    path,
    index: start,
    delete_count: current.length - start - end,
    values: next.slice(start, next.length - end),
  };
}

function crdtMutations(
  field: string,
  current: unknown,
  next: unknown,
  policy: CrdtPolicy,
  change?: StoreChange,
): CrdtMutation[] {
  const path = keyPath(field);
  if (
    policy.kind === "sequence" &&
    policy.materialization === "string" &&
    typeof current === "string" &&
    typeof next === "string"
  )
    return stringSplices(current, next, path, change);
  if (
    policy.kind === "sequence" &&
    policy.materialization !== "string" &&
    Array.isArray(current) &&
    Array.isArray(next)
  )
    return [arraySplice(current, next, path)];
  if (policy.kind === "register")
    return [{ kind: "register_set", path, value: next }];
  throw new TypeError(
    `two-way binding for CRDT ${policy.kind} field ${JSON.stringify(field)} is not supported`,
  );
}

function crdtPolicy(spec: CrdtSpecView, field: string): CrdtPolicy {
  const value = "toObject" in spec ? spec.toObject() : spec;
  let policy = value.root;
  for (const key of field.split(".")) {
    if (policy.kind !== "map")
      throw new TypeError(
        `CRDT field ${JSON.stringify(field)} does not follow map policies`,
      );
    const next = policy.fields?.[key] ?? policy.values;
    if (!next)
      throw new TypeError(
        `CRDT field ${JSON.stringify(field)} is absent from the model specification`,
      );
    policy = next;
  }
  return policy;
}

function crdtFields(change: { ops: CrdtOp[] }): string[] | undefined {
  const fields = new Set<string>();
  for (const op of change.ops) {
    const head = op.path[0];
    if (head?.kind === "key") fields.add(head.key);
    else if (
      !head &&
      (op.kind === "map_set" || op.kind === "map_remove") &&
      op.key
    )
      fields.add(op.key);
    else return undefined;
  }
  return [...fields];
}

/**
 * Bidirectionally sync a `Store` with a transports-mirrored model. Model fields map by name to store
 * fields — and a nested sub-model flattens to dotted `parent.child` fields: inbound frames pull them
 * into the store; a store field change (e.g. from a two-way control) is pushed back through the client.
 * Plain models use server-authoritative proposals. CRDT models use their declared merge
 * policy and update optimistically while transports retains the operations for reconnect.
 *
 * Pass a `namespace` to mirror under `${namespace}.<field>` so several models can share one `Store`
 * without their field names colliding (e.g. two `Chart` models on one page); the outbound edit still
 * carries the bare model field. Call it once per model. Explicit selectors can share a client across namespaces.
 *
 * `flatten` (default true) recurses nested sub-models into dotted `parent.child` fields — what a generated
 * form binds to. Set it false when a top-level field is an **opaque map/dict** (a chart's time-keyed
 * `data`, a Perspective layout): the field is mirrored whole, so replacing it is one store set + one edit
 * (not one per key), and `compute`/`bind` read the whole value.
 *
 * Current transports clients expose accepted snapshots and patches through `onChange`; `connectStore`
 * subscribes automatically, including when the client owns the connection. With an older client,
 * `StoreLink.receive` falls back to the value mirrored by `recv`.
 */
export function connectStore(
  store: Store,
  client: ModelClient,
  send: ((frame: string | Uint8Array) => unknown) | undefined,
  codec: ValueCodec,
  namespace?: string, // prefix every store field with `${namespace}.` — lets several models share one Store
  flatten = true, // recurse nested sub-models to dotted fields; set false to keep an opaque map/dict whole
  model?: number | string, // exact ID or unique snapshot type; omitted retains first-model discovery
): StoreLink {
  if (
    model !== undefined &&
    !(typeof model === "string"
      ? model.length > 0
      : Number.isSafeInteger(model) && model >= 0)
  )
    throw new TypeError(
      "model must be a nonempty type name or a nonnegative safe integer ID",
    );
  if (typeof model === "string" && !client.typeName)
    throw new TypeError(
      "type-name selection requires a transports client with typeName",
    );
  let id: number | undefined;
  let selectionError: string | undefined;
  const modelListeners = new Set<(id: number) => void>();
  let inbound = false; // true while applying a received frame, so we don't echo it straight back out
  let disposed = false;
  let disconnected = false;
  let crdtBacked = false;
  const wired = new Set<string>();
  const fieldUnsubs = new Map<string, () => void>();
  const unsubs: Array<() => void> = [];
  const pending = new Map<string, { field: string; value: unknown }>();
  const latest = new Map<string, string>();
  // A recovery snapshot precedes its reject; retain field names without retaining optimistic values.
  const recovered = new Map<string, string>();
  const proposalAware =
    client.editOps !== undefined &&
    client.onAck !== undefined &&
    client.onReject !== undefined &&
    client.onAbandon !== undefined &&
    client.abandonProposal !== undefined;
  const managedCrdt =
    client.editCrdt !== undefined && client.proposeCrdt !== undefined;
  if (
    send === undefined &&
    (!proposalAware || client.proposeOps === undefined) &&
    !managedCrdt
  )
    throw new TypeError(
      "connectStore requires send or a proposal-aware client with proposeOps",
    );

  const dropProposal = (proposal: string): string | undefined => {
    const edit = pending.get(proposal);
    if (!edit) return undefined;
    pending.delete(proposal);
    if (latest.get(edit.field) === proposal) {
      latest.delete(edit.field);
      for (const [candidate, pendingEdit] of pending) {
        if (pendingEdit.field === edit.field) latest.set(edit.field, candidate);
      }
    }
    return edit.field;
  };

  const discardProposal = (proposal: string): string | undefined => {
    client.abandonProposal?.(proposal);
    return dropProposal(proposal);
  };

  const storeField = (field: string) =>
    namespace ? `${namespace}.${field}` : field;
  const errorField = (field: string) => `$errors.${storeField(field)}`;
  const clearError = (field: string) => store.set(errorField(field), "");
  const publishReject = (reject: RejectChange, field?: string) => {
    if (typeof document === "undefined" || typeof CustomEvent === "undefined")
      return;
    document.dispatchEvent(
      new CustomEvent("spaday:reject", {
        detail: {
          id: reject.id,
          model: namespace,
          field: field === undefined ? undefined : storeField(field),
          error: reject.error,
          proposal: reject.proposal,
          rev: reject.rev,
        },
      }),
    );
  };

  const readPlainPath = (value: unknown, parts: string[]): unknown => {
    let current = value;
    for (const part of parts) {
      if (!isObj(current)) return undefined;
      current = current[part];
    }
    return current;
  };

  const overlayPending = (field: string, value: unknown): unknown => {
    let overlaid = value;
    for (const [proposal, edit] of pending) {
      if (latest.get(edit.field) !== proposal) continue;
      if (edit.field === field) {
        overlaid = edit.value;
      } else if (edit.field.startsWith(`${field}.`)) {
        overlaid = setPath(
          isObj(overlaid) ? overlaid : {},
          edit.field.slice(field.length + 1).split("."),
          edit.value,
        );
      } else if (field.startsWith(`${edit.field}.`)) {
        overlaid = readPlainPath(
          edit.value,
          field.slice(edit.field.length + 1).split("."),
        );
      }
    }
    return overlaid;
  };

  const wireField = (field: string) => {
    const key = namespace ? `${namespace}.${field}` : field;
    if (wired.has(key)) return;
    wired.add(key);
    fieldUnsubs.set(
      key,
      store.subscribe(key, (_value, changedKey, change) => {
        if (inbound || id === undefined) return;
        const effectiveKey =
          changedKey === key || changedKey.startsWith(`${key}.`)
            ? changedKey
            : key;
        const changedField = namespace
          ? effectiveKey.slice(namespace.length + 1)
          : effectiveKey;
        const value = store.get(effectiveKey);
        const changedErrorField = crdtBacked
          ? changedField.split(".")[0]
          : changedField;
        clearError(changedErrorField);
        for (const [proposal, field] of recovered)
          if (field === changedField) recovered.delete(proposal);
        if (disconnected) {
          queueReconcile(changedField);
          return;
        }
        const decoded = codec.fromValue(client.value(id));
        const current = isObj(decoded) ? decoded : {};
        if (crdtBacked && client.editCrdt) {
          const spec = client.crdtSpec?.(id);
          if (!spec)
            throw new TypeError(
              "CRDT-backed clients must expose their model specification",
            );
          try {
            const mutations =
              client.crdtDiff && !change?.ranges.length
                ? client.crdtDiff(id, value, changedField.split("."))
                : crdtMutations(
                    changedField,
                    readPlainPath(current, changedField.split(".")),
                    value,
                    crdtPolicy(spec, changedField),
                    change,
                  );
            if (mutations.length) {
              if (send === undefined && client.proposeCrdt)
                client.proposeCrdt(id, mutations);
              else send?.(client.editCrdt(id, mutations));
            }
            // Sets have canonical order; a reorder-only edit must also restore that order.
            if (client.crdtDiff) queueReconcile(changedField);
          } catch (error) {
            store.set(errorField(changedErrorField), String(error));
            queueReconcile(changedField);
            throw error;
          }
          return;
        }
        const ownerField = changedField.split(".")[0];
        if (client.owns?.(id, ownerField) && client.editOps) {
          // Ownership is whole-field; nested bindings replace that field without a proposal.
          const next = setPath(current, changedField.split("."), value);
          const ops: PatchOp[] = [
            {
              Set: {
                path: [{ Key: ownerField }],
                value: codec.toValue(next[ownerField]),
              },
            },
          ];
          try {
            const sent =
              send === undefined && client.proposeOps
                ? client.proposeOps(id, ops)
                : send?.(client.editOps(id, ops));
            if (sent === false) queueReconcile(changedField);
          } catch (error) {
            queueReconcile(changedField);
            throw error;
          }
          return;
        }
        if (!proposalAware) {
          send!(
            client.edit(
              id,
              codec.toValue(setPath(current, changedField.split("."), value)),
            ),
          );
          return;
        }
        const proposal = `spaday-${nextStoreProposal++}`;
        const ops: PatchOp[] = [
          {
            Set: {
              path: changedField.split(".").map((part) => ({ Key: part })),
              value: codec.toValue(value),
            },
          },
        ];
        pending.set(proposal, { field: changedField, value });
        latest.set(changedField, proposal);
        try {
          const sent =
            send === undefined && client.proposeOps
              ? client.proposeOps(id, ops, proposal)
              : send
                ? send(client.editOps!(id, ops, proposal))
                : false;
          if (sent === false) {
            discardProposal(proposal);
            queueReconcile(changedField);
          }
        } catch (error) {
          discardProposal(proposal);
          queueReconcile(changedField);
          throw error;
        }
      }),
    );
  };

  const unwireBranch = (field: string) => {
    const key = namespace ? `${namespace}.${field}` : field;
    for (const [candidate, unsub] of fieldUnsubs) {
      if (candidate !== key && !candidate.startsWith(`${key}.`)) continue;
      unsub();
      fieldUnsubs.delete(candidate);
      wired.delete(candidate);
    }
  };

  const unwireFields = () => {
    for (const unsub of fieldUnsubs.values()) unsub();
    fieldUnsubs.clear();
    wired.clear();
  };

  const receiveSnapshot = (fields?: Iterable<string>) => {
    if (id === undefined) return;
    const decoded = codec.fromValue(client.value(id));
    if (!isObj(decoded)) return;
    if (!fields && crdtBacked) {
      // A snapshot can remove map keys that leaf-by-leaf writes would leave behind.
      fields = new Set([
        ...Object.keys(decoded),
        ...[...wired].map((key) =>
          namespace ? key.slice(namespace.length + 1) : key,
        ),
      ]);
    }
    if (fields) {
      for (const field of new Set(
        [...fields].map((candidate) => candidate.split(".")[0]),
      )) {
        unwireBranch(field);
        store.set(storeField(field), overlayPending(field, decoded[field]));
        wireField(field);
      }
      return;
    }
    unwireFields();
    const entries = flatten ? leaves(decoded) : Object.entries(decoded);
    for (const [field, value] of entries) {
      const key = namespace ? `${namespace}.${field}` : field;
      store.set(key, overlayPending(field, value));
    }
    for (const field of Object.keys(decoded)) wireField(field);
  };

  const reconcile = (fields?: Iterable<string>) => {
    inbound = true;
    try {
      receiveSnapshot(fields);
    } finally {
      inbound = false;
    }
  };

  let reconcileQueued = false;
  const queuedReconcileFields = new Set<string>();
  const queueReconcile = (field: string) => {
    if (disposed) return;
    queuedReconcileFields.add(field);
    if (reconcileQueued) return;
    reconcileQueued = true;
    queueMicrotask(() => {
      reconcileQueued = false;
      if (disposed) return;
      const fields = [...queuedReconcileFields];
      queuedReconcileFields.clear();
      reconcile(fields);
    });
  };

  const receivePatch = (
    change: Extract<ReceiveChange, { t: "patch" }>,
    settledField?: string,
  ) => {
    const staged = new Map<
      string,
      {
        field: string;
        value: unknown;
        deltas?: CollectionDelta[];
      }
    >();
    const authoritativeFields = new Set<string>();
    if (settledField) authoritativeFields.add(settledField.split(".")[0]);
    for (const field of latest.keys())
      authoritativeFields.add(field.split(".")[0]);
    let authoritative: Record<string, unknown> | undefined;
    try {
      for (const op of change.patch.ops) {
        const body =
          "Set" in op
            ? op.Set
            : "Remove" in op
              ? op.Remove
              : "Insert" in op
                ? op.Insert
                : "RemoveAt" in op
                  ? op.RemoveAt
                  : "Move" in op
                    ? op.Move
                    : op.Reorder;
        const [head, ...rest] = body.path;
        if (!head) {
          receiveSnapshot();
          return;
        }
        if (!("Key" in head))
          throw new Error("model patch path must start with a map key");
        const field = head.Key;
        const key = namespace ? `${namespace}.${field}` : field;
        if (authoritativeFields.has(field)) {
          if (!authoritative) {
            const decoded = codec.fromValue(client.value(change.id));
            if (!isObj(decoded))
              throw new Error("model value must be an object");
            authoritative = decoded;
          }
          staged.set(key, { field, value: authoritative[field] });
          continue;
        }
        const current = staged.has(key)
          ? staged.get(key)!.value
          : store.get(key);
        const value = applyPlainOp(current, rest, op, codec);
        const itemKey = store.collectionKey(key);
        let deltas = staged.has(key)
          ? staged.get(key)!.deltas
          : itemKey
            ? []
            : undefined;
        if (deltas && itemKey) {
          const delta = collectionDelta(current, value, rest, op, itemKey);
          if (delta) deltas.push(delta);
          else deltas = undefined;
        }
        staged.set(key, {
          field,
          value,
          deltas,
        });
      }
    } catch {
      receiveSnapshot();
      return;
    }
    for (const [key, update] of staged) {
      unwireBranch(update.field);
      const itemKey = store.collectionKey(key);
      const current = store.get(key);
      update.value = overlayPending(update.field, update.value);
      if (
        update.deltas &&
        itemKey &&
        Array.isArray(update.value) &&
        Array.isArray(current) &&
        collectionDeltasMatch(current, update.value, update.deltas, itemKey)
      )
        store.setCollection(key, update.value, update.deltas);
      else store.set(key, update.value);
      wireField(update.field);
    }
  };

  const select = (candidate: number | undefined): boolean => {
    if (selectionError) return false;
    if (typeof model === "string") {
      const matches = client
        .ids()
        .filter((mid) => client.typeName!(mid) === model);
      const changedType = id !== undefined && client.typeName!(id) !== model;
      if (matches.length > 1 || changedType) {
        selectionError = changedType
          ? `Selected model ${id} no longer has type ${JSON.stringify(model)}`
          : `Ambiguous model type ${JSON.stringify(model)}; select a numeric model ID`;
        for (const proposal of [...pending.keys()]) discardProposal(proposal);
        const fields = [...fieldUnsubs.keys()];
        unwireFields();
        id = undefined;
        for (const field of fields) store.set(field, undefined);
        if (typeof document !== "undefined")
          document.dispatchEvent(
            new CustomEvent("spaday:wire-error", {
              detail: { namespace, model, error: selectionError },
            }),
          );
        return false;
      }
      if (matches[0] !== candidate || candidate === undefined) return false;
    } else if (model !== undefined && candidate !== model) return false;
    if (id === undefined) id = candidate;
    return id !== undefined && candidate === id;
  };

  const accept = (change: ReceiveChange) => {
    if (disposed) return;
    const discovered = id === undefined;
    if (!select(change.id)) return;
    if (change.t === "snapshot") {
      crdtBacked = false;
      recovered.clear();
      for (const [field, proposal] of latest) recovered.set(proposal, field);
      for (const proposal of [...pending.keys()]) discardProposal(proposal);
    } else if (change.t === "crdt_snapshot") {
      crdtBacked = true;
    }
    const settledField =
      change.t === "patch" && change.proposal
        ? dropProposal(change.proposal)
        : undefined;
    inbound = true;
    try {
      if (change.t === "patch") receivePatch(change, settledField);
      else if (change.t === "crdt") receiveSnapshot(crdtFields(change));
      else receiveSnapshot();
      if (settledField) clearError(settledField);
    } finally {
      inbound = false;
    }
    if (discovered)
      for (const listener of [...modelListeners]) listener(change.id);
  };

  const listensForChanges = client.onChange !== undefined;
  if (client.onChange) unsubs.push(client.onChange(accept));
  if (client.onAck)
    unsubs.push(
      client.onAck((ack) => {
        if (id === undefined || ack.id !== id || ack.proposal === undefined)
          return;
        recovered.delete(ack.proposal);
        const field = dropProposal(ack.proposal);
        if (field !== undefined) {
          clearError(field);
          reconcile([field]);
        }
      }),
    );
  if (client.onReject)
    unsubs.push(
      client.onReject((reject) => {
        if (id === undefined || reject.id !== id) return;
        const fields = new Set<string>();
        if (crdtBacked && reject.crdt_ops) {
          const rejected = crdtFields({ ops: reject.crdt_ops }) ?? [];
          for (const field of rejected) {
            fields.add(field);
            store.set(errorField(field), reject.error);
          }
          publishReject(
            reject,
            rejected.length === 1 ? rejected[0] : undefined,
          );
        } else if (reject.proposal) {
          const edit = pending.get(reject.proposal);
          const field = edit?.field ?? recovered.get(reject.proposal);
          const latestRejected =
            edit !== undefined
              ? latest.get(edit.field) === reject.proposal
              : field !== undefined && !latest.has(field);
          discardProposal(reject.proposal);
          recovered.delete(reject.proposal);
          if (field !== undefined) fields.add(field);
          if (field !== undefined && latestRejected)
            store.set(errorField(field), reject.error);
          publishReject(reject, field);
        } else {
          const pendingFields = [...new Set(latest.keys())];
          for (const field of pendingFields) fields.add(field);
          for (const proposal of [...pending.keys()]) discardProposal(proposal);
          for (const field of pendingFields)
            store.set(errorField(field), reject.error);
          publishReject(reject);
        }
        if (fields.size) reconcile(fields);
      }),
    );
  const abandon = (proposals: Iterable<string>) => {
    const fields = new Set<string>();
    recovered.clear();
    for (const proposal of proposals) {
      const field = dropProposal(proposal);
      if (field !== undefined) fields.add(field);
    }
    if (fields.size) reconcile(fields);
  };
  if (client.onAbandon)
    unsubs.push(client.onAbandon((proposals) => abandon(proposals)));

  if (model !== undefined) {
    const existing = client
      .ids()
      .find((mid) =>
        typeof model === "number"
          ? mid === model
          : client.typeName!(mid) === model,
      );
    if (existing !== undefined)
      accept({
        t: client.crdtSpec?.(existing) ? "crdt_snapshot" : "snapshot",
        id: existing,
      });
  }

  return {
    get error() {
      return selectionError;
    },
    get modelId() {
      return id;
    },
    onModel(listener) {
      if (disposed) return () => {};
      modelListeners.add(listener);
      if (id !== undefined) listener(id);
      return () => modelListeners.delete(listener);
    },
    receive(data) {
      disconnected = false;
      const change = client.recv(data);
      // Current transports clients deliver only accepted snapshots/patches through onChange. A stale
      // patch, reject, or future message type therefore does no store work. Older clients have no
      // listener API, so retain their recv-return/full-snapshot compatibility paths below.
      if (listensForChanges) return;
      if (Array.isArray(change)) {
        for (const accepted of change) accept(accepted);
        return;
      }
      if (change) {
        accept(change);
        return;
      }
      const discovered = id === undefined;
      const candidate =
        typeof model === "number"
          ? client.ids().includes(model)
            ? model
            : undefined
          : typeof model === "string"
            ? client.ids().find((mid) => client.typeName!(mid) === model)
            : (id ?? client.ids()[0]);
      if (!select(candidate)) return; // no matching model yet
      inbound = true;
      try {
        receiveSnapshot();
      } finally {
        inbound = false;
      }
      if (discovered) for (const listener of [...modelListeners]) listener(id!);
    },
    disconnect() {
      if (disposed) return;
      disconnected = true;
      const proposals = [...pending.keys()];
      for (const proposal of proposals) client.abandonProposal?.(proposal);
      abandon(proposals);
    },
    dispose() {
      disposed = true;
      recovered.clear();
      for (const proposal of [...pending.keys()]) discardProposal(proposal);
      unwireFields();
      for (const unsub of unsubs) unsub();
      modelListeners.clear();
    },
  };
}
